// The app's ORIGINAL apparatus schematic (tool/illustrations/schematic/*.svg,
// LabGuide's own work — docs/SCHEMATICS_PROVENANCE.md), inlined and animated:
// numbered callouts fade/pulse, a camera push-in, an optional light beam.
import React from 'react';
// @ts-ignore generated by scripts/prepare.mjs
import {schematics} from '../generated/schematics.js';
import {color} from '../design/theme';

type Sch = {
  svg: string;
  callouts: Record<string, {badge: [number, number] | null; target: [number, number] | null}>;
  viewBox: [number, number, number, number];
};

export function schematic(key: string): Sch {
  const s = (schematics as unknown as Record<string, Sch>)[key];
  if (!s) throw new Error(`schematic ${key} missing — run scripts/prepare.mjs`);
  return s;
}

export const SchematicStage: React.FC<{
  name: string;
  width: number;
  /** callout number -> emphasis 0..1 (others are dimmed). */
  emphasis: Record<number, number>;
  /** 0..1 how much non-emphasised callouts are dimmed. */
  dim: number;
  zoom?: number;
  focus?: [number, number];
  beam?: {from: [number, number]; to: [number, number]; t: number; pulse: number} | null;
}> = ({name, width, emphasis, dim, zoom = 1, focus, beam}) => {
  const s = schematic(name);
  const [, , vw, vh] = s.viewBox;
  const scale = width / vw;
  const height = vh * scale;
  const f = focus ?? [vw / 2, vh / 2];
  const css = Object.keys(s.callouts)
    .map((n) => {
      const e = emphasis[Number(n)] ?? 0;
      const op = 1 - dim * 0.82 * (1 - e);
      const sc = 1 + 0.18 * e;
      const b = s.callouts[n].badge ?? [0, 0];
      return `.lg-${name} .callout[data-n="${n}"]{opacity:${op.toFixed(3)};transform-box:view-box;transform-origin:${b[0]}px ${b[1]}px;transform:scale(${sc.toFixed(3)})}`;
    })
    .join('\n');
  return (
    <div style={{position: 'relative', width, height, overflow: 'visible'}}>
      <div
        style={{
          position: 'absolute',
          inset: 0,
          transformOrigin: `${f[0] * scale}px ${f[1] * scale}px`,
          transform: `scale(${zoom})`,
        }}
      >
        <style>{css}</style>
        <div style={{position: 'absolute', inset: 0}} dangerouslySetInnerHTML={{__html: s.svg}} />
        <svg
          viewBox={s.viewBox.join(' ')}
          width={width}
          height={height}
          style={{position: 'absolute', inset: 0, overflow: 'visible'}}
        >
          <defs>
            <linearGradient id={`beam-${name}`} x1="0" x2="1">
              <stop offset="0" stopColor={color.beam} stopOpacity="0.2" />
              <stop offset="1" stopColor={color.beam} stopOpacity="1" />
            </linearGradient>
          </defs>
          {Object.entries(emphasis).map(([n, e]) => {
            const t = s.callouts[n]?.target;
            if (!t || e <= 0.01) return null;
            return (
              <circle
                key={n}
                cx={t[0]}
                cy={t[1]}
                r={14 + 16 * e}
                fill="none"
                stroke={color.mint}
                strokeWidth={3}
                opacity={0.8 * e}
              />
            );
          })}
          {beam && beam.t > 0 ? (
            <g>
              <line
                x1={beam.from[0]}
                y1={beam.from[1]}
                x2={beam.from[0] + (beam.to[0] - beam.from[0]) * beam.t}
                y2={beam.from[1] + (beam.to[1] - beam.from[1]) * beam.t}
                stroke={color.beam}
                strokeWidth={12}
                strokeLinecap="round"
                opacity={0.22 + 0.12 * beam.pulse}
              />
              <line
                x1={beam.from[0]}
                y1={beam.from[1]}
                x2={beam.from[0] + (beam.to[0] - beam.from[0]) * beam.t}
                y2={beam.from[1] + (beam.to[1] - beam.from[1]) * beam.t}
                stroke={`url(#beam-${name})`}
                strokeWidth={4}
                strokeLinecap="round"
              />
            </g>
          ) : null}
        </svg>
      </div>
    </div>
  );
};
